// === Tab: mySketch ===
p5.disableFriendlyErrors = true;



let myShader;

function preload() {

  myShader = loadShader("https://openprocessing.org/sketch/1287263/files/vert.txt", "frag.txt");
}

function setup() {
  createCanvas(1000, 1000, WEBGL);
  noStroke();
}

function draw() {
  background(0);

  shader(myShader);


  myShader.setUniform("uFrameCount", frameCount*1);

  rotateX(frameCount * 0.001);
  rotateZ(frameCount * 0.001);
  rotateZ(frameCount * 0.001);

  // Draw some geometry to the screen
  // We're going to tessellate the sphere a bit so we have some more geometry to work with
  sphere(width / 6, 200, 200);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

